import numpy as np
t=df['t'].values; A=df['A'].values; r=df['dA_dt'].values
FB={'1':np.ones_like(t),'e':np.exp(-t),'1/t':1/t,'t':t,'log':np.log(t),'sq':np.sqrt(t),'1/t2':1/t**2,'t2':t**2,'e2':np.exp(-2*t),'1/sq':1/np.sqrt(t)}
GB={'1':np.ones_like(t),'log':np.log(t),'sq':np.sqrt(t),'e':np.exp(-t),'t':t,'1/t':1/t,'e2':np.exp(-2*t)}
def run(fk,gk):
    X=np.vstack([FB[k] for k in fk]+[GB[k]*A**2 for k in gk]).T
    c,_,_,_=np.linalg.lstsq(X,r,rcond=None)
    return np.mean((X@c-r)**2)/np.var(r),c
